import{_ as r,a}from"./chunks/540b2ac07da5d6916fb1.D6CU62GD.js";import{_ as o,C as n,o as l,c as i,j as p,a as s,E as h,a6 as m}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"6个月改变你的生活（我的深度工作日常）","description":"","frontmatter":{"title":"6个月改变你的生活（我的深度工作日常）","originalTitle":"Change Your Life In 6 Months (My Deep Work Routine)","date":"2023-03-18","originalUrl":"https://thedankoe.com/letters/change-your-life-in-6-months-my-deep-work-routine/","minutes":7,"sourceHash":"39b96afe394001558601e0719d3ac8f09e6d105081b243ce97e35e52c1d97238","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/change-your-life-in-6-months-my-deep-work-routine/"}]]},"headers":[],"relativePath":"letters/change-your-life-in-6-months-my-deep-work-routine.md","filePath":"letters/change-your-life-in-6-months-my-deep-work-routine.md"}'),d={name:"letters/change-your-life-in-6-months-my-deep-work-routine.md"};function c(u,e,f,k,_,b){const t=n("ArticleMeta");return l(),i("div",null,[e[0]||(e[0]=p("h1",{id:"_6个月改变你的生活-我的深度工作日常",tabindex:"-1"},[s("6个月改变你的生活（我的深度工作日常） "),p("a",{class:"header-anchor",href:"#_6个月改变你的生活-我的深度工作日常","aria-label":'Permalink to "6个月改变你的生活（我的深度工作日常）"'},"​")],-1)),h(t),e[1]||(e[1]=m('<p><a href="https://www.youtube.com/embed/ZdO00Y-u1y0?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em>如果你能花8小时去构建别人的梦想，你就能花1小时去构建自己的梦想。</em></p><p>我最近在思考的一个最强大的理念是：</p><p>将你理想的未来带入现在。</p><p>也就是说，为你未来将要过的生活方式投入时间，但在一个更小的时间尺度上执行相同的行动。</p><p>举个例子，在我的余生里，我想每天早上写作2小时。</p><p>这能<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">产生基础收入</a>，清理我的思绪，并让我在每天早上培养我的创造力。</p><p>首先，我意识到这一点的唯一途径就是不断尝试。</p><p>其次，除非你现在就去尝试你想要的东西，否则你不会知道自己真正想要什么，在这个过程中你只会意识到自己不想要什么。这就是生活方式迭代的过程。</p><p>当你将理想未来中的具体行动带入现在时，你就在为那种生活方式投入能量。</p><p>根据我的“概念生存法则”，你将做出决定去维持这些日常习惯。</p><blockquote><p><strong>概念生存法则：</strong> <em>一种人类现象，我们的生存本能已经超越了物理领域，并</em> <em>融入了</em> <em>精神层面</em>_。我们努力维持那些构成我们自我认同的思想、概念和信念的存活。_</p></blockquote><p>如果有什么东西威胁到了你维持理想生活方式的能力，你就会将其视为一个问题。</p><p>你的大脑会通过这个视角来看待各种情况，并记录下潜在的解决方案。你可以在社交媒体、书本中，或者说任何地方找到这些解决方案。</p><p>这就是为什么我鼓励人们重温他们最喜欢的书。</p><p>我猜你已经有了更明确的目标。你会通过这个视角去读书，并找到能帮助你当前事业的经验教训。</p><p><strong>这里的教训是：</strong></p><p>如果你不是在为你理想的未来努力，你就是在为别人的理想未来打工。</p><p>你的时间会根据感知到的重要性被填满，所以要通过向你的目标投入能量来创造这种重要性。</p><h2 id="全面的日常作息" tabindex="-1">全面的日常作息 <a class="header-anchor" href="#全面的日常作息" aria-label="Permalink to &quot;全面的日常作息&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>每天你需要留出专属的时间用于创造、产出和实验。</p><p>人们脑海中浮现的第一个反对意见是：“可是Dan，我没有足够的时间啊！”</p><p>没关系。</p><p>我不是让你一整天都做这些。</p><p>我是让你在你能做到的最短时间内去做。15分钟左右。因为你心理的健康取决于此。你的天性并不适应现代生活，如果它对你来说已经习以为常，那么从定义上讲，你已经被困在了“矩阵（母体）”中。</p><p>你们中的许多人对我<a href="https://thedankoe.com/the-3-part-daily-routine-for-maximum-productivity/" target="_blank" rel="noreferrer">如何安排我的一天</a>已经很熟悉了，所以我会长话短说。</p><p>你需要3种活动来全力追求你的目标：</p><ul><li><strong>一种能充实大脑的活动</strong> —— 你需要教育、理念和能应用于你目标的新颖资源。这会带来内在动力。</li><li><strong>一种能放空大脑的活动</strong> —— 你不会想被困在充斥着各种思绪和有用想法的混乱气泡中。那正是你原地踏步的原因。把事情写下来。</li><li><strong>一种能使用大脑的活动</strong> —— 你需要一个载体来集中你的精力。带着你的想法和清晰的执行力，去构建你的未来。</li></ul><p>这封信将重点关注最后一点，即通过深度工作来使用你的大脑。</p><h2 id="深度工作的必要性" tabindex="-1">深度工作的必要性 <a class="header-anchor" href="#深度工作的必要性" aria-label="Permalink to &quot;深度工作的必要性&quot;">​</a></h2><blockquote><p>你是谁，你想什么，感受什么，做什么，你爱什么——都是你所关注事物的总和。—— Cal Newport</p></blockquote><p>生产力是关于在尽可能短的时间内完成最有效的工作。</p><p>生产力不是看谁能工作得最久，并把它当成一种荣誉勋章。</p><p>我们在<a href="https://thedankoe.com/life-is-hard-get-used-to-it-the-way-to-mental-mastery/" target="_blank" rel="noreferrer">之前的一封信中</a>讨论过一个重要的概念，叫做感知阈值。</p><p>感知阈值是指，在克服了阻力之后，曾经困难的事情变得毫不费力的临界点。</p><p>当我们通过工作将能量投入到一个目标中时，即使一开始我们并不觉得这是自己热爱的事情，我们也会迎来一个突破口，在这个突破口我们<em>变得</em>对这项工作充满热情。</p><p>如果我们将能量投入到能带来理想未来的事情上，当失去动力时，我们会感觉好像在浪费这种能量。而拥有动力的感觉很好……准确地说，是不可思议的好。</p><p>在一个充满消息通知、过多选择和令人不知所措的世界里，深度工作已不再是一个可选项。</p><p>如果你想改变自己的生活，它就是一种<em>必需品</em>。</p><p>深度工作是你如何在创纪录的时间内构筑梦想的方式。</p><h2 id="优先级阶梯" tabindex="-1">优先级阶梯 <a class="header-anchor" href="#优先级阶梯" aria-label="Permalink to &quot;优先级阶梯&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>每天纯粹专注1小时，你就能在6个月内彻底改变你的生活。</p><p>这就是你需要的一切。</p><p>1小时。</p><p>所以这就是我们将要开始的地方。</p><p>首先，我想介绍一下我称之为<em>优先级阶梯</em>的概念。</p><p>优先级阶梯是一种构建你专注工作时段的方法。</p><p>我们从一个基于未来目标的高优先级项目开始。</p><p>在那个时间块之后，我们接着运用我们的创造力去做高杠杆任务……那些我们没有、也不应该外包的任务。</p><p>接下来，我们转向与我们的创意工作相一致的有意义的任务。</p><p>第四个是维护性任务，以及向世界展示你自己的任务。</p><p>所有这些时间块都应该持续60-90分钟，然后再休息。</p><p>随着每一个时间块的推进，你逐渐引入分心的可能。但第一个时间块必须是绝对无干扰的。</p><h3 id="优先级-1-–-愿景构建" tabindex="-1">优先级 1 – 愿景构建 <a class="header-anchor" href="#优先级-1-–-愿景构建" aria-label="Permalink to &quot;优先级 1 – 愿景构建&quot;">​</a></h3><p>如果你每天时间不多，这是你唯一需要关注的时间块。没有借口。</p><p>如果你连抽出一小时来构建对你有意义的东西都做不到……那肯定有什么需要改变了。要快。做出牺牲会痛苦，但这是必要的。</p><p>在这60-90分钟的时间块里：</p><p>开启一个项目，它应当是你理想生活方式拼图中的一块。</p><p>对大多数人来说，这将围绕着学习新技能以推进他们的职业生涯，或者<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">开启一人企业</a>展开。</p><p>你在这个时间块里采取的行动应该能撬动杠杆。</p><p>杠杆 = 真正推动你走向新见解、新进展或新结果的东西。</p><p>如果你在创业，一开始就写Newsletter（新闻邮件）是很愚蠢的（<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">除非你使用我的系统</a>）。</p><p>你没有读者。</p><p>你没有可以用来变现的报价（Offer）。</p><p>你没有真正获得读者的方法。</p><p>相反，你需要通过课程、书本或互联网内容来自我教育，弄清楚杠杆究竟是什么。</p><p>一个更好的起点将是经典的社交媒体增长公式：</p><ul><li>在大号上留下10-30条回复（因为他们的受众是一个流量源，可以点击你的个人主页并关注你）。</li><li>每天发送5-10条私信，使用不显渴求的人脉建立流程（这样你就能有朋友分享你的内容，你需要曝光）。</li><li>练习写能传播给新读者的短内容。</li></ul><p>一旦你掌握了这一点，你就是在积累流量了。</p><p>然后，你需要一个可以迭代的最小可行性报价。这样，你就能将流量变现。</p><p>随着你的流程变得越来越高效，它们占用的时间就会减少，你就可以开始灵活调整你的深度工作计划了。</p><h3 id="优先级-2-–-高杠杆创意工作" tabindex="-1">优先级 2 – 高杠杆创意工作 <a class="header-anchor" href="#优先级-2-–-高杠杆创意工作" aria-label="Permalink to &quot;优先级 2 – 高杠杆创意工作&quot;">​</a></h3><p>在新经济中，你的想法是你脱颖而出的关键。</p><p>如果你想产生关注、收入和权威，你必须每天分发这些想法。</p><p>如果你把产生想法外包出去，你就在你的成长道路上竖起了一堵墙。内容代运营机构是可以产生流量，但再次强调，你们都知道我在这方面的理念。</p><p>在我的第二个时间块，我会优先写我的Newsletter。</p><p>长文写作就像是在充实一个庞大想法的深度。</p><p>把它想象成解构一个大想法，把它写下来，然后再重新建构一个新想法。</p><p><em>创造力是炼金术，只不过材料是想法。</em></p><p>对于刚起步的人来说，你最好把精力集中在为社交媒体平台写内容上，以产生流量。</p><p>但我不会推迟写长内容，因为它将决定你未来想法的质量，从而决定你未来品牌的质量。</p><h3 id="优先级-3-–-有意义的任务与溢出任务" tabindex="-1">优先级 3 – 有意义的任务与溢出任务 <a class="header-anchor" href="#优先级-3-–-有意义的任务与溢出任务" aria-label="Permalink to &quot;优先级 3 – 有意义的任务与溢出任务&quot;">​</a></h3><p>我的第三个时间块用来写社交媒体内容或录制视频。</p><p>有时候，我脑海中冒出的随机想法已经攒成了足够的内容，我就会把它们丢进 <a href="https://thedankoe.com/get/tweethunter" target="_blank" rel="noreferrer">TweetHunter</a>（这是我所有内容的起点，我会从这交叉发布到所有平台）。</p><p>在这种情况下，我会试着赶上其他进度，或者去跟进我正在做的其他项目（比如我正在开发的灵感捕捉软件）。</p><p>简而言之，这个时间块应该留给那些你不打算外包的有意义的任务。</p><p>并且我建议你<em>永远</em>不要外包你的创意开发。</p><p>我想我永远都不会外包：</p><ul><li>我的Newsletter写作（这会变成YouTube视频）</li><li>我的推文写作（这会变成Instagram、LinkedIn内容、短视频脚本等）。</li></ul><p>真的就是这些，这些就是我根本的杠杆。</p><h3 id="优先级-4-–-维护性任务" tabindex="-1">优先级 4 – 维护性任务 <a class="header-anchor" href="#优先级-4-–-维护性任务" aria-label="Permalink to &quot;优先级 4 – 维护性任务&quot;">​</a></h3><p>就我而言，到这个阶段差不多是上午9:30到10点。</p><p>我已经搞定了所有能保持我的业务健康并持续增长的工作。</p><p>现在，我把重心放在维护我的产品和服务的任务上，比如登录Modern Mastery看看、回复消息以及查收邮件。</p><p>我把这个留到我工作时段的最后，因为哪怕只是一条消息，也能毁掉你整个深度工作时段。</p><p>绝对的专注让你能在2小时内完成8小时的工作，直到你真正做到，你才会意识到这一点。</p><p>这篇Newsletter比我其他的文章大约少了1000字，但我觉得我已经把要点说清楚了。</p><p>去测试一下，做些实验看看什么对你有效，然后享受你这一天剩下的时光吧。</p><p>– Dan</p><hr><p><a href="/en/letters/change-your-life-in-6-months-my-deep-work-routine">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',103))])}const q=o(d,[["render",c]]);export{w as __pageData,q as default};
